class ValidationException(Exception):
    def __init__(
        self, errors: Sequence[Any], *, endpoint_context: Optional[Dict[str, Any]] = None
    ) -> None:
        self._errors = errors
        self._endpoint_context = endpoint_context

    def errors(self) -> Sequence[Any]:
        return self._errors

    def _format_endpoint_context(self) -> str:
        if self._endpoint_context:
            ctx = self._endpoint_context
            return (
                f"\n    File: {ctx.get('file', '<unknown>')}, "
                f"line: {ctx.get('line', '<unknown>')}, "
                f"in: {ctx.get('name', '<unknown>')}\n"
                f"    Method: {ctx.get('method', '<unknown>')}, "
                f"Route: {ctx.get('route', '<unknown>')}\n"
            )
        return ""


class RequestValidationError(ValidationException):
    def __init__(
        self,
        errors: Sequence[Any],
        *,
        body: Any = None,
        endpoint_context: Optional[Dict[str, Any]] = None,
    ) -> None:
        super().__init__(errors, endpoint_context=endpoint_context)
        self.body = body

    def __str__(self) -> str:
        message = f"{len(self._errors)} validation error(s) for request"
        message += self._format_endpoint_context()
        for err in self._errors:
            message += f"  {err}\n"
        return message


class WebSocketRequestValidationError(ValidationException):
    def __init__(
        self,
        errors: Sequence[Any],
        *,
        endpoint_context: Optional[Dict[str, Any]] = None,
    ) -> None:
